/**
 * Compute the default session directory for a cwd.
 * Encodes cwd into a safe directory name under ~/.pi/agent/sessions/.
 *
 * The encoding is a shared contract with the legacy session migration
 * (see migrations.ts) and the agent session repo: drop one leading separator,
 * then replace every `/`, `\\` and `:` with `-`. Backslashes and colons must be
 * encoded even though this runs on POSIX, because a POSIX cwd may legitimately
 * contain Windows-style path fragments.
 */
function getDefaultSessionDirPath(cwd: string, agentDir: string = getDefaultAgentDir()): string {
	const resolvedCwd = resolvePath(cwd);
	const resolvedAgentDir = resolvePath(agentDir);
	const safePath = `--${resolvedCwd.replace(/^[/\\]/, "").replace(/[/\\:]/g, "-")}--`;
	return join(resolvedAgentDir, "sessions", safePath);
}

// Compute the correct session directory. This must stay byte-identical to
// getDefaultSessionDirPath() in core/session-manager.ts, i.e. drop one
// leading separator and replace every `/`, `\\` and `:` with `-`.
const safePath = `--${cwd.replace(/^[/\\]/, "").replace(/[/\\:]/g, "-")}--`;

